def compute_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # n = 2k, k = n // 2
        k = n // 2
        result = 2 * compute_a(k, memo) + k
    else:
        # n = 2k + 1, k = (n - 1) // 2
        k = (n - 1) // 2
        # a_{2k+1} = a_k + a_{k+1} + k
        result = compute_a(k, memo) + compute_a(k + 1, memo) + k

    memo[n] = result
    return result

N = 2025
